 Chapter 8 Beta diversity Between-sample dissimilarity using Hill-based distances (richness, neutral, phylogenetic, functional), PERMANOVA tests for broad environment/island effects, and NMDS ordinations to visualise separation in community structure. Note: Load all required data objects including genome counts, metadata, and color schemes. load(&quot;data/data.Rdata&quot;) treatment_colors &lt;- c(&quot;#f56042&quot;,&quot;#429ef5&quot;, &quot;#42f58d&quot;, &quot;#b142f5&quot;, &quot;#f5e642&quot;) Note: Filter out sample EHI01340, identify valid samples, remove samples with missing broad_environment values, and filter genome counts to only include valid samples. sample_metadata &lt;- sample_metadata %&gt;% dplyr::filter(sample != &quot;EHI01340&quot;) valid_samples &lt;- sample_metadata$sample sample_metadata_without_NA &lt;- sample_metadata %&gt;% dplyr::filter(!is.na(broad_environment)) genome_counts_filt &lt;- genome_counts_filt %&gt;% dplyr::select(genome, tidyselect::any_of(valid_samples)) beta_div Note: Calculate four types of beta diversity distance matrices using Hill-based pairwise distances: richness-based (q=0, presence/absence), neutral/abundance-weighted (q=1), phylogenetic (q=1 with phylogenetic tree), and functional (q=1 with functional trait distances). Filters out genomes and samples with zero counts before calculation. #Presence/Absence beta_q0n &lt;- genome_counts_filt %&gt;% tibble::column_to_rownames(., &quot;genome&quot;) %&gt;% dplyr::filter(rowSums(. != 0, na.rm = TRUE) &gt; 0) %&gt;% dplyr::select_if(~!all(. == 0)) %&gt;% hillpair(., q = 0) #Abundance-sensitive beta_q1n &lt;- genome_counts_filt %&gt;% tibble::column_to_rownames(., &quot;genome&quot;) %&gt;% dplyr::filter(rowSums(. != 0, na.rm = TRUE) &gt; 0) %&gt;% dplyr::select_if(~!all(. == 0)) %&gt;% hillpair(., q = 1) #Abundance + Phylogeny genome_counts_filt_beta &lt;- genome_counts_filt %&gt;% tibble::column_to_rownames(., &quot;genome&quot;) %&gt;% dplyr::filter(rowSums(. != 0, na.rm = TRUE) &gt; 0) %&gt;% dplyr::select_if(~!all(. == 0)) %&gt;% tibble::rownames_to_column(., &quot;genome&quot;) #Abundance + Trait Distance genome_tree &lt;- keep.tip(genome_tree, tip = genome_counts_filt_beta$genome) beta_q1p &lt;- genome_counts_filt %&gt;% tibble::column_to_rownames(., &quot;genome&quot;) %&gt;% dplyr::filter(rowSums(. != 0, na.rm = TRUE) &gt; 0) %&gt;% dplyr::select_if(~!all(. == 0)) %&gt;% hillpair(., q = 1, tree = genome_tree) Note: Calculate functional beta diversity (beta_q1f) by matching genomes between count data and functional trait data (genome_gifts). Converts GIFT traits to elements, calculates Gower distance matrix, filters and aligns both datasets to common genomes, then computes Hill-based pairwise distances with functional trait distances. # Create genome_counts_filt_beta if it doesn&#39;t exist (from beta_div chunk) if (!exists(&quot;genome_counts_filt_beta&quot;)) { genome_counts_filt_beta &lt;- genome_counts_filt %&gt;% tibble::column_to_rownames(., &quot;genome&quot;) %&gt;% dplyr::filter(rowSums(. != 0, na.rm = TRUE) &gt; 0) %&gt;% dplyr::select_if(~!all(. == 0)) %&gt;% tibble::rownames_to_column(., &quot;genome&quot;) } # 1. Only use genomes that also occur in genome_gifts valid_genomes &lt;- genome_counts_filt_beta$genome[genome_counts_filt_beta$genome %in% rownames(genome_gifts)] # 2. filter genome_gifts on these genomes genome_gifts1 &lt;- genome_gifts[valid_genomes, ] genome_gifts1 &lt;- genome_gifts1[, colSums(genome_gifts1 != 0) &gt; 0] # 3. Calculate functional distance matrix dist &lt;- genome_gifts1 %&gt;% to.elements(., GIFT_db) %&gt;% traits2dist(., method = &quot;gower&quot;) # 4. Determine genomes that exist in both genome_counts_filt_beta and dist common_genomes &lt;- intersect( genome_counts_filt_beta$genome, rownames(dist) ) # 5. genome_counts_filt to filter and sort the shared genomes genome_counts_filt_matched &lt;- genome_counts_filt %&gt;% tibble::column_to_rownames(&quot;genome&quot;) %&gt;% dplyr::filter(rownames(.) %in% common_genomes) %&gt;% dplyr::select_if(~!all(. == 0)) # optional: remove empty columns # 6. Limit and sort dist matrix to common genomes dist_matched &lt;- dist[common_genomes, common_genomes] beta_q1f &lt;- genome_counts_filt_matched %&gt;% hillpair(q = 1, dist = dist_matched) Note: Save all four beta diversity distance matrices (richness, neutral, phylogenetic, functional) to an R data file for later use. Note: Set random seed for reproducibility of permutation-based statistical tests. 8.1 Permanova Note: Define a reusable function run_permanova that performs PERMANOVA analysis on beta diversity matrices. The function matches samples between distance matrix and metadata, filters out NAs, tests beta dispersion (homogeneity of variances), runs PERMANOVA with adonis2, optionally performs pairwise comparisons, and returns both dispersion and PERMANOVA results. run_permanova &lt;- function(beta_matrix, metadata, sample_col = &quot;sample&quot;, group_col, group_vars, pairwise = FALSE) { # 1. Sample labels from Beta-Matrix (dist object) sample_labels &lt;- labels(beta_matrix$S) # 2. Metadata filtered and sorted metadata_matched &lt;- metadata %&gt;% dplyr::filter(!!rlang::sym(sample_col) %in% sample_labels) %&gt;% dplyr::arrange(match(!!rlang::sym(sample_col), sample_labels)) # 3. Synchronize beta_matrix$S to metadata (subset via matrix, then back to dist) common_samples &lt;- intersect(sample_labels, metadata_matched[[sample_col]]) S_mat &lt;- as.matrix(beta_matrix$S) S_mat &lt;- S_mat[common_samples, common_samples, drop = FALSE] beta_matrix$S &lt;- as.dist(S_mat) metadata_matched &lt;- metadata_matched %&gt;% dplyr::filter(!!rlang::sym(sample_col) %in% common_samples) %&gt;% dplyr::arrange(match(!!rlang::sym(sample_col), common_samples)) # 4. Remove samples with NA in group_col (again via matrix → dist) valid_idx &lt;- !is.na(metadata_matched[[group_col]]) S_mat &lt;- as.matrix(beta_matrix$S) S_mat &lt;- S_mat[valid_idx, valid_idx, drop = FALSE] beta_matrix$S &lt;- as.dist(S_mat) metadata_matched &lt;- metadata_matched[valid_idx, ] # 5. Betadisper and Permutest cat(&quot;
===== Beta Dispersion Test =====
&quot;) dispersion_result &lt;- betadisper(beta_matrix$S, metadata_matched[[group_col]]) print(permutest(dispersion_result)) # 6. Dynamic formula building formula_str &lt;- paste0(&quot;beta_matrix$S ~ &quot;, paste(group_vars, collapse = &quot; + &quot;)) cat(&quot;
===== PERMANOVA Test (adonis2) =====
&quot;) permanova_result &lt;- adonis2( as.formula(formula_str), data = metadata_matched, permutations = 999, by = &quot;terms&quot; ) print(broom::tidy(permanova_result)) # 7. (Optional) Pairwise Adonis if (pairwise) { cat(&quot;
===== Pairwise PERMANOVA =====
&quot;) print(pairwise.adonis(beta_matrix$S, metadata_matched[[group_col]], perm = 999)) } # 8. Return outputs return(list( dispersion = dispersion_result, permanova = permanova_result )) } 8.1.1 Richness Note: Run PERMANOVA analysis on richness-based beta diversity (beta_q0n) to test for differences in community composition across broad environment types and islands, including interaction effects. Tests whether presence/absence community structure differs between environments. run_permanova( beta_matrix = beta_q0n, metadata = sample_metadata_without_NA, sample_col = &quot;sample&quot;, group_col = &quot;broad_environment&quot;, group_vars = c(&quot;broad_environment&quot;, &quot;island&quot;, &quot;broad_environment:island&quot;), pairwise = FALSE ) ===== Beta Dispersion Test ===== Permutation test for homogeneity of multivariate dispersions Permutation: free Number of permutations: 999 Response: Distances Df Sum Sq Mean Sq F N.Perm Pr(&gt;F) Groups 4 0.34450 0.086126 24.942 999 0.001 *** Residuals 67 0.23135 0.003453 --- Signif. codes: 0 &#39;***&#39; 0.001 &#39;**&#39; 0.01 &#39;*&#39; 0.05 &#39;.&#39; 0.1 &#39; &#39; 1 ===== PERMANOVA Test (adonis2) ===== # A tibble: 4 × 6 term df SumOfSqs R2 statistic p.value &lt;chr&gt; &lt;dbl&gt; &lt;dbl&gt; &lt;dbl&gt; &lt;dbl&gt; &lt;dbl&gt; 1 broad_environment 4 3.59 0.135 3.09 0.001 2 island 1 3.93 0.147 13.5 0.001 3 Residual 66 19.2 0.718 NA NA 4 Total 71 26.7 1 NA NA $dispersion Homogeneity of multivariate dispersions Call: betadisper(d = beta_matrix$S, group = metadata_matched[[group_col]]) No. of Positive Eigenvalues: 71 No. of Negative Eigenvalues: 0 Average distance to median: 1000198 - Mixed forest 1000215 - Temperate shrubland 1000218 - Xeric shrubland 1000221 - Temperate woodland 0.4214 0.4098 0.4631 0.6067 1000245 - Cropland 0.5154 Eigenvalues for PCoA axes: (Showing 8 of 71 eigenvalues) PCoA1 PCoA2 PCoA3 PCoA4 PCoA5 PCoA6 PCoA7 PCoA8 4.3803 2.9152 1.3249 1.2293 1.0689 1.0209 0.8381 0.7413 $permanova Permutatio