 Define a reusable function to create NMDS ordination plots. The function performs metaMDS on the distance matrix, extracts NMDS scores, joins with sample metadata, calculates group centroids, and visualizes samples with optional labels. # Function to calculate overall axis limits from all beta matrices calculate_nmds_limits &lt;- function(beta_matrices) { all_scores &lt;- purrr::map_dfr(beta_matrices, function(beta_mat) { beta_mat$S %&gt;% vegan::metaMDS(trymax = 500, k = 2, trace = 0) %&gt;% vegan::scores() %&gt;% tibble::as_tibble(rownames = &quot;sample&quot;) }) x_range &lt;- range(all_scores$NMDS1, na.rm = TRUE) y_range &lt;- range(all_scores$NMDS2, na.rm = TRUE) # Add some padding (5% on each side) x_padding &lt;- diff(x_range) * 0.05 y_padding &lt;- diff(y_range) * 0.05 list( xlim = c(x_range[1] - x_padding, x_range[2] + x_padding), ylim = c(y_range[1] - y_padding, y_range[2] + y_padding) ) } create_nmds_plot &lt;- function(beta_matrix, show_labels = FALSE, point_size = 3, segment_alpha = 0.3, show_ellipses = FALSE, show_centroids = TRUE, xlim = NULL, ylim = NULL) { # Calculate NMDS and get stress value nmds_obj &lt;- beta_matrix$S %&gt;% vegan::metaMDS(trymax = 500, k = 2, trace = 0) stress_value &lt;- nmds_obj$stress # Extract scores and join with metadata nmds_scores &lt;- nmds_obj %&gt;% vegan::scores() %&gt;% tibble::as_tibble(rownames = &quot;sample&quot;) %&gt;% dplyr::inner_join(sample_metadata, by = join_by(sample == sample)) %&gt;% group_by(broad_environment) %&gt;% mutate( x_cen = mean(NMDS1, na.rm = TRUE), y_cen = mean(NMDS2, na.rm = TRUE) ) %&gt;% ungroup() # Create base plot p &lt;- nmds_scores %&gt;% ggplot(aes(x = NMDS1, y = NMDS2, color = broad_environment, shape = as.factor(island))) + # Add segments from centroids to points (lighter and thinner) geom_segment( aes(x = x_cen, y = y_cen, xend = NMDS1, yend = NMDS2), alpha = segment_alpha, linewidth = 0.3, color = &quot;gray60&quot;, show.legend = FALSE ) + # Add sample points geom_point(size = point_size, alpha = 0.8) + # Color scale with proper capitalization scale_color_manual( values = treatment_colors, labels = c(&quot;tasmania&quot; = &quot;Tasmania&quot;, &quot;australia&quot; = &quot;Australia&quot;) ) + # Shape scale scale_shape_discrete(name = &quot;Island&quot;) # Add confidence ellipses if requested if (show_ellipses) { p &lt;- p + stat_ellipse( aes(color = broad_environment), type = &quot;norm&quot;, level = 0.95, linetype = 2, alpha = 0.5, linewidth = 0.5, show.legend = FALSE ) } # Add centroid markers if requested if (show_centroids) { p &lt;- p + geom_point( data = nmds_scores %&gt;% dplyr::distinct(broad_environment, x_cen, y_cen), aes(x = x_cen, y = y_cen, color = broad_environment), shape = 21, size = 6, stroke = 2, fill = &quot;white&quot;, show.legend = FALSE ) } # Add theme and labels p &lt;- p + # Theme theme( axis.title = element_text(size = 12, face = &quot;bold&quot;), axis.text = element_text(size = 10), panel.background = element_blank(), panel.grid.major = element_line(color = &quot;gray90&quot;, linewidth = 0.3), panel.grid.minor = element_blank(), axis.line = element_line(size = 0.5, linetype = &quot;solid&quot;, colour = &quot;black&quot;), legend.text = element_text(size = 10), legend.title = element_text(size = 11, face = &quot;bold&quot;), legend.position = &quot;right&quot;, legend.box = &quot;vertical&quot;, legend.spacing = unit(0.5, &quot;cm&quot;), legend.key.size = unit(1, &quot;lines&quot;) ) + # Labels with stress value in title labs( title = paste0(&quot;NMDS (Stress = &quot;, round(stress_value, 3), &quot;)&quot;), x = &quot;NMDS1&quot;, y = &quot;NMDS2&quot;, color = &quot;Environmental context&quot;, shape = &quot;Island&quot; ) + # Legend guides guides( color = guide_legend(order = 1, override.aes = list(size = 3)), shape = guide_legend(order = 2, override.aes = list(size = 3)) ) # Add coordinate system with fixed limits if provided if (!is.null(xlim) &amp;&amp; !is.null(ylim)) { p &lt;- p + coord_fixed(ratio = 1, xlim = xlim, ylim = ylim, expand = TRUE) } else { p &lt;- p + coord_fixed(ratio = 1, expand = TRUE) } # Text labels removed - no longer adding sample IDs return(p) } Note: Calculate overall axis limits from all beta diversity matrices to ensure consistent scaling across all NMDS plots. # Calculate limits once from all beta matrices nmds_limits &lt;- calculate_nmds_limits(list(beta_q0n, beta_q1n, beta_q1p, beta_q1f)) ###Richness Note: Create NMDS ordination plot for richness-based beta diversity. Performs metaMDS on the distance matrix, extracts NMDS scores, joins with sample metadata, calculates group centroids for each broad environment, and visualizes samples colored by environment and shaped by island, with segments connecting samples to their group centroids. create_nmds_plot(beta_q0n, show_labels = FALSE, xlim = nmds_limits$xlim, ylim = nmds_limits$ylim) 8.2.1 Neutral diversity Note: Create NMDS ordination plot for abundance-weighted beta diversity. Performs metaMDS on the distance matrix, extracts NMDS scores, joins with sample metadata, calculates group centroids for each broad environment, and visualizes samples colored by environment and shaped by island, with segments connecting samples to their group centroids. create_nmds_plot(beta_q1n, show_labels = FALSE, xlim = nmds_limits$xlim, ylim = nmds_limits$ylim) 8.2.2 Phylogenetic diversity Note: Create NMDS ordination plot for phylogenetic beta diversity. Performs metaMDS on the distance matrix, extracts NMDS scores, joins with sample metadata, calculates group centroids for each broad environment, and visualizes samples colored by environment and shaped by island, with segments connecting samples to their group centroids. create_nmds_plot(beta_q1p, show_labels = FALSE, xlim = nmds_limits$xlim, ylim = nmds_limits$ylim) 8.2.3 Functional diversity Note: Create NMDS ordination plot for functional beta diversity. Performs metaMDS on the distance matrix, extracts NMDS scores, joins with sample metadata, calculates group centroids for each broad environment, and visualizes samples colored by environment and shaped by island, with segments connecting samples to their group centroids. create_nmds_plot(beta_q1f, show_labels = FALSE, xlim = nmds_limits$xlim, ylim = nmds_limits$ylim) Note: Create a zoomed-in version of the functional diversity NMDS plot with axes fitted to the data range for better visualization of the functional diversity patterns. The y-axis is stretched with additional padding for improved visibility. # Calculate functional diversity specific limits with more y-axis padding func_nmds_obj &lt;- beta_q1f$S %&gt;% vegan::metaMDS(trymax = 500, k = 2, trace = 0) func_scores &lt;- func_nmds_obj %&gt;% vegan::scores() %&gt;% tibble::as_tibble(rownames = &quot;sample&quot;) x_range_func &lt;- range(func_scores$NMDS1, na.rm = TRUE) y_range_func &lt;- range(func_scores$NMDS2, na.rm = TRUE) # Add padding: 5% for x-axis, 15% for y-axis (more stretch on y) x_padding_func &lt;- diff(x_range_func) * 0.05 y_padding_func &lt;- diff(y_range_func) * 0.50 func_limits &lt;- list( xlim = c(x_range_func[1] - x_padding_func, x_range_func[2] + x_padding_func), ylim = c(y_range_func[1] - y_padding_func, y_range_func[2] + y_padding_func) ) create_nmds_plot(beta_q1f, show_labels = FALSE, xlim = func_limits$xlim, ylim = func_limits$ylim)
